  print(tag,result,flush=True);page.wait_for_selector('[data-story-tool="history"]');snapshot=page.evaluate('JSON.stringify({dialogue:HonroApp.dialogue,docs:HonroApp.profile.honroEvidenceDocuments,steps:HonroApp.engine.b.honroAct2Steps,state:HonroApp.engine.b.honroState.act2})')
